// Generated from src/registry/sources/control-ui/recipes/label.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const labelKnobs = ["--cui-label-root-foreground"] as const;
export type LabelKnobStyle = Partial<Record<(typeof labelKnobs)[number], string>>;

@layer components {
  :where([data-control-family="label"][data-slot="root"]) {
    --cui-label-root-foreground: var(--muted-foreground);
    color: var(--cui-label-root-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="field"][data-control="true"]:disabled ~ [data-control-family="label"][data-slot="root"]) {
    opacity: 70%;
  }
}

@property --cui-label-root-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";
import type { LabelKnobStyle } from "@/components/control-ui/knob-contracts/label-knobs";

export type LabelProps = Omit<ComponentProps<"label">, "style"> & { style?: CSSProperties & LabelKnobStyle };

// renders real <label> when htmlFor is set, else a <span> for group captions
export function Label({ className, htmlFor, children, ...props }: LabelProps) {
  const classes = className;

  if (htmlFor) {
    return (
      <label data-control-ui="label" data-control-family="label" data-slot="root" htmlFor={htmlFor} className={classes} {...props}>
        {children}
      </label>
    );
  }

  return (
    <span data-control-ui="label" data-control-family="label" data-slot="root" className={classes} {...props}>
      {children}
    </span>
  );
}
